/**
 * Learner-facing evaluation response submission.
 * @module     local_airpay_evaluation/response_actions
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 *
 * P1 #31 (2026-05-20) — adds conditional question show/hide that
 * mirrors evaluation_manager::compute_visibility_map() server-side.
 * Hand-converted from amd/src/response_actions.js — keep the two in
 * lockstep when changing either.
 */
define("local_airpay_evaluation/response_actions", [
    "core/str",
    "core/notification",
    "core/ajax"
], function(Str, Notification, Ajax) {
    "use strict";

    var setButtonContent = function(btn, iconClass, text) {
        while (btn.firstChild) { btn.removeChild(btn.firstChild); }
        if (iconClass) {
            var i = document.createElement("i");
            i.className = iconClass;
            i.setAttribute("aria-hidden", "true");
            btn.appendChild(i);
            btn.appendChild(document.createTextNode(" "));
        }
        btn.appendChild(document.createTextNode(text));
    };

    var readCardValue = function(card) {
        var qtype = card.dataset.questiontype;
        if (qtype === "text") {
            var ta = card.querySelector("textarea");
            var v = ta ? ta.value.trim() : "";
            return v === "" ? null : v;
        }
        if (qtype === "numeric") {
            var input = card.querySelector('input[type="number"]');
            return (input && input.value.trim() !== "") ? input.value.trim() : null;
        }
        if (qtype === "multichoice_multi") {
            var checked = card.querySelectorAll('input[type="checkbox"]:checked');
            var picks = Array.prototype.map.call(checked, function(cb) { return cb.value; });
            return picks.length > 0 ? JSON.stringify(picks) : null;
        }
        var radio = card.querySelector('input[type="radio"]:checked');
        return radio ? radio.value : null;
    };

    var computeVisibility = function(root) {
        var cards = Array.prototype.slice.call(
            root.querySelectorAll(".question-card"));
        var answers = new Map();
        for (var i = 0; i < cards.length; i++) {
            var qid = parseInt(cards[i].dataset.questionid || "0", 10);
            if (!qid) continue;
            answers.set(qid, readCardValue(cards[i]));
        }

        var visible = new Map();
        for (var j = 0; j < cards.length; j++) {
            var card = cards[j];
            var cqid = parseInt(card.dataset.questionid || "0", 10);
            if (!cqid) continue;
            var parentQid = parseInt(card.dataset.dependsOnQid || "0", 10);
            if (parentQid <= 0) {
                visible.set(cqid, true);
                continue;
            }
            if (!visible.get(parentQid)) {
                visible.set(cqid, false);
                continue;
            }
            var parentAnswer = answers.get(parentQid);
            if (parentAnswer === null || parentAnswer === "") {
                visible.set(cqid, false);
                continue;
            }
            var needed = card.dataset.dependsOnValue || "";
            if (needed === "") {
                visible.set(cqid, true);
                continue;
            }
            var parentCard = root.querySelector(
                '.question-card[data-questionid="' + parentQid + '"]');
            var parentType = parentCard ? parentCard.dataset.questiontype : "";
            if (parentType === "multichoice_multi") {
                var arr;
                try { arr = JSON.parse(parentAnswer); } catch (e) { arr = []; }
                visible.set(cqid, Array.isArray(arr)
                    && arr.map(String).indexOf(needed) !== -1);
            } else {
                visible.set(cqid,
                    String(parentAnswer).trim() === needed.trim());
            }
        }
        return visible;
    };

    var clearCardInputs = function(card) {
        var checkedRadios = card.querySelectorAll('input[type="radio"]:checked');
        for (var i = 0; i < checkedRadios.length; i++) checkedRadios[i].checked = false;
        var checkedCbs = card.querySelectorAll('input[type="checkbox"]:checked');
        for (var j = 0; j < checkedCbs.length; j++) checkedCbs[j].checked = false;
        var tas = card.querySelectorAll("textarea");
        for (var k = 0; k < tas.length; k++) tas[k].value = "";
        var nums = card.querySelectorAll('input[type="number"]');
        for (var n = 0; n < nums.length; n++) nums[n].value = "";
    };

    var applyVisibility = function(root, vis) {
        var cards = root.querySelectorAll(".question-card");
        for (var i = 0; i < cards.length; i++) {
            var card = cards[i];
            var qid = parseInt(card.dataset.questionid || "0", 10);
            if (!qid) continue;
            var shouldShow = vis.get(qid) !== false;
            var wasVisible = card.style.display !== "none";
            if (shouldShow && !wasVisible) {
                card.style.display = "";
            } else if (!shouldShow && wasVisible) {
                card.style.display = "none";
                clearCardInputs(card);
            } else if (!shouldShow) {
                clearCardInputs(card);
            }
        }
    };

    var collectAnswers = function(root) {
        var cards = root.querySelectorAll(".question-card");
        var answers = {};
        var missing = null;
        for (var i = 0; i < cards.length; i++) {
            var card = cards[i];
            if (card.style.display === "none") continue;
            var qid = card.dataset.questionid;
            var required = card.dataset.required === "1";
            var value = readCardValue(card);
            if (required && (value === null || value === "")) {
                missing = card;
                break;
            }
            if (value !== null && value !== "") {
                answers[qid] = value;
            }
        }
        return {answers: answers, missing: missing};
    };

    var submit = function(root) {
        var result = collectAnswers(root);
        var answers = result.answers, missing = result.missing;
        if (missing) {
            missing.scrollIntoView({behavior: "smooth", block: "center"});
            missing.style.outline = "2px solid #dc2626";
            missing.style.outlineOffset = "4px";
            setTimeout(function() {
                missing.style.outline = "";
                missing.style.outlineOffset = "";
            }, 2400);
            Str.get_string("please_answer_required", "local_airpay_evaluation")
                .then(function(msg) {
                    Notification.addNotification({message: msg, type: "warning"});
                    return null;
                });
            return;
        }

        var evaluationid = parseInt(root.dataset.evaluationid || "0", 10);
        var context = {
            courseid: parseInt(root.dataset.contextCourseid || "0", 10),
            programid: parseInt(root.dataset.contextProgramid || "0", 10),
            classroomid: parseInt(root.dataset.contextClassroomid || "0", 10),
        };

        var btn = root.querySelector('[data-action="submit-response"]');
        if (btn) {
            btn.disabled = true;
            setButtonContent(btn, "fa fa-spinner fa-spin fa-fw", "Submitting...");
        }

        Ajax.call([{
            methodname: "local_airpay_evaluation_submit_response",
            args: {
                evaluationid: evaluationid,
                answers: JSON.stringify(answers),
                context: JSON.stringify(context),
            }
        }])[0].then(function() {
            Str.get_string("response_submitted", "local_airpay_evaluation")
                .then(function(success) {
                    Notification.addNotification({message: success, type: "success"});
                    setTimeout(function() { window.location.reload(); }, 600);
                    return null;
                });
            return null;
        }).catch(function(err) {
            Notification.exception(err);
            if (btn) {
                btn.disabled = false;
                setButtonContent(btn, "fa fa-paper-plane fa-fw", "Submit Response");
            }
        });
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        if (trigger.dataset.action !== "submit-response") return;
        event.preventDefault();
        var root = document.querySelector('[data-region="airpay-eval-respond"]');
        if (root) submit(root);
    };

    var wireVisibility = function(root) {
        var recompute = function() {
            applyVisibility(root, computeVisibility(root));
        };
        root.addEventListener("change", recompute);
        root.addEventListener("input", recompute);
        recompute();
    };

    return {
        init: function() {
            var root = document.querySelector('[data-region="airpay-eval-respond"]');
            if (!root || root.dataset.airpayResponseInit === "1") return;
            root.dataset.airpayResponseInit = "1";
            root.addEventListener("click", handleClick);
            wireVisibility(root);
        }
    };
});
